open_ports = {}

def check_port(ip):
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(1)
    try:
        sock.connect((str(ip), port))
        open_ports[str(ip)] = True
    except socket.error:
        open_ports[str(ip)] = False
    finally:
        sock.close()

